# 인터페이스에 체크 예외를 두면
public interface MemberRepositoryEx {
    Member save(Member member) throws SQLException;
    Member findById(String memberId) throws SQLException;
}

# 서비스
public void accountTransfer(...) throws SQLException {   <- 또 번진다
    memberRepository.findById(fromId);
}

# 6 장에서 없앤 throws 가 돌아왔다

# 메모리 구현을 만들면
public class MemoryMemberRepository implements MemberRepositoryEx {
    public Member save(Member member) throws SQLException {
        store.put(member.getMemberId(), member);   // SQL 이 안 나간다
        return member;
    }
}

# 테스트
MemberService service = new MemberService(new MemoryMemberRepository());
service.accountTransfer("memberA", "memberB", 2000);

#   (SQL 로그가 하나도 없다)
#   (커넥션 로그도 없다)
#   테스트가 0.01 초에 끝난다

# 그런데 여전히
try {
    service.accountTransfer(...);
} catch (SQLException e) { }    <- 절대 안 나는 예외

# throws 를 없애면
public interface MemberRepository {
    Member save(Member member);
}

# JDBC 구현이 컴파일 오류
#   Exception SQLException is not compatible with throws clause
